 1	function sorted(s : seq<int>) : bool {
 2	  forall k1, k2 :: 0 <= k1 <= k2 < |s| ==> s[k1] <= s[k2]
 3	}
 4	
 5	
 6	// Ex1
 7	
 8	method copyArr(a : array<int>, l : int, r : int) returns (ret : array<int>)
 9	  requires 0 <= l < r <= a.Length 
10	  ensures ret[..] == a[l..r]
11	{
12	  var size := r - l;
13	  ret := new int[size];
14	  var i := 0;
15	  
16	  while(i < size)
17	    invariant a[..] == old(a[..])
18	    invariant 0 <= i <= (size) + 1
19	    invariant ret[..i] == a[l..(l + i)]
20	    decreases size - i
21	  {
22	    ret[i] := a[i + l];
23	    i := i + 1;
24	  }
25	  return;
26	}
27	
28	
29	// Ex2
30	
31	method mergeArr(a : array<int>, l : int, m : int, r : int)
32	  requires 0 <= l < m < r <= a.Length  
33	  requires sorted(a[l..m]) && sorted(a[m..r])
34	  ensures sorted(a[l..r]) 
35	  ensures a[..l] == old(a[..l])
36	  ensures a[r..] == old(a[r..])
37	  modifies a 
38	{
39	  var left := copyArr(a, l, m);
40	  var right := copyArr(a, m, r);
41	  var i := 0;
42	  var j := 0;
43	  var cur := l;
44	  ghost var old_arr := a[..];
45	  while(cur < r) 
46	    decreases a.Length - cur
47	    invariant 0 <= i <= left.Length
48	    invariant 0 <= j <= right.Length
49	    invariant l <= cur <= r
50	    invariant cur == i + j + l
51	    invariant a[..l] == old_arr[..l]
52	    invariant a[r..] == old_arr[r..]
53	    invariant sorted(a[l..cur])
54	    invariant sorted(left[..])
55	    invariant sorted(right[..])
56	    invariant i < left.Length && cur > l ==> a[cur - 1] <= left[i] 
57	    invariant j < right.Length && cur > l ==> a[cur - 1] <= right[j]
58	  {
59	    if((i == left.Length && j < right.Length) || (j != right.Length && left[i] > right[j])) {
60	      a[cur] := right[j];
61	      j := j + 1;
62	    }
63	    else if((j == right.Length && i < left.Length) || (i != left.Length && left[i] <= right[j])) {
64	      a[cur] := left[i];
65	      i := i + 1;
66	    }
67	    cur := cur + 1;
68	  }
69	  return;
70	}
71	
72	// Ex3
73	
74	method sort(a : array<int>) 
75	  ensures sorted(a[..])
76	  modifies a
77	{
78	  if(a.Length == 0) { return; }
79	  else { sortAux(a, 0, a.Length); }
80	}
81	
82	method sortAux(a : array<int>, l : int, r : int)
83	  ensures sorted(a[l..r])
84	  ensures a[..l] == old(a[..l])
85	  ensures a[r..] == old(a[r..])
86	  requires 0 <= l < r <= a.Length
87	  modifies a
88	  decreases r - l
89	{
90	  if(l >= (r - 1)) {return;}
91	  else {
92	    var m := l + (r - l) / 2;
93	    sortAux(a, l, m);
94	    sortAux(a, m, r);
95	    mergeArr(a, l, m, r);
96	    return;
97	  }
98	}

